import random
from collections import deque

def would_create_short_cycle(adj, u, v, n, min_girth=7):
    """Check if adding edge (u,v) would create a cycle shorter than min_girth"""
    dist = [-1] * n
    dist[u] = 0
    queue = deque([u])
    while queue:
        node = queue.popleft()
        if dist[node] >= min_girth - 2:
            break
        for neighbor in adj[node]:
            if dist[neighbor] == -1:
                dist[neighbor] = dist[node] + 1
                queue.append(neighbor)
    return dist[v] != -1 and dist[v] < min_girth - 1

def compute_girth(adj, n):
    min_cycle = float('inf')
    for u in range(n):
        dist = [-1] * n
        dist[u] = 0
        queue = deque([u])
        while queue:
            node = queue.popleft()
            for neighbor in adj[node]:
                if dist[neighbor] == -1:
                    dist[neighbor] = dist[node] + 1
                    queue.append(neighbor)
                elif dist[neighbor] >= dist[node]:
                    cycle_len = dist[node] + dist[neighbor] + 1
                    min_cycle = min(min_cycle, cycle_len)
    return min_cycle

def try_random_construction(n, target_edges, min_girth, max_attempts=1000):
    best_edges = []

    for attempt in range(max_attempts):
        adj = [set() for _ in range(n)]
        edges = []

        all_possible_edges = [(u, v) for u in range(n) for v in range(u+1, n)]
        random.shuffle(all_possible_edges)

        for u, v in all_possible_edges:
            if not would_create_short_cycle(adj, u, v, n, min_girth):
                adj[u].add(v)
                adj[v].add(u)
                edges.append((u, v))

        if len(edges) > len(best_edges):
            best_edges = edges[:]
            print(f"Attempt {attempt}: {len(edges)} edges")
            if len(edges) >= target_edges:
                return edges, adj

    return best_edges, None

random.seed(42)
result_edges, result_adj = try_random_construction(21, 21, 7, max_attempts=200)
print(f"\nBest found: {len(result_edges)} edges")
